"""Role-based page access guard demo using Reflex."""

import hashlib
import secrets

import reflex as rx

# ---------------------------------------------------------------------------
# Password hashing helpers
# ---------------------------------------------------------------------------

def _hash_password(password: str, salt: str) -> str:
    """Return a hex digest of the password + salt using SHA-256."""
    dk = hashlib.pbkdf2_hmac(
        "sha256", password.encode(), salt.encode(), 260_000
    )
    return dk.hex()


def _make_entry(password: str) -> dict:
    """Return a dict with a freshly-generated salt and the derived hash."""
    salt = secrets.token_hex(32)
    return {"salt": salt, "hash": _hash_password(password, salt)}


# ---------------------------------------------------------------------------
# User "database" – built once at module-load time, lives only on the server
# ---------------------------------------------------------------------------

_USERS: dict[str, dict] = {
    "admin": {**_make_entry("s3cure-admin-pw"), "role": "admin"},
    "alice": {**_make_entry("s3cure-user-pw"), "role": "user"},
}


# ---------------------------------------------------------------------------
# Application state
# ---------------------------------------------------------------------------

class State(rx.State):
    """Global application state.

    Attributes starting with ``_`` are backend-only: Reflex never serialises
    them and sends them to the browser, so credentials/session data are safe.
    """

    # --- backend-only session fields ---
    _username: str = ""
    _role: str = ""
    _login_error: str = ""

    # --- computed vars derived from backend state ---

    @rx.var
    def is_authenticated(self) -> bool:
        return bool(self._username)

    @rx.var
    def is_admin(self) -> bool:
        return self._role == "admin"

    @rx.var
    def current_username(self) -> str:
        return self._username

    @rx.var
    def current_role(self) -> str:
        return self._role

    @rx.var
    def login_error(self) -> str:
        return self._login_error

    # --- actions ---

    def login(self, form_data: dict) -> rx.EventSpec | None:
        """Validate credentials; on success redirect to /dashboard."""
        username: str = form_data.get("username", "").strip()
        password: str = form_data.get("password", "")

        entry = _USERS.get(username)
        if entry is not None:
            expected = _hash_password(password, entry["salt"])
            if secrets.compare_digest(expected, entry["hash"]):
                self._username = username
                self._role = entry["role"]
                self._login_error = ""
                return rx.redirect("/dashboard")

        # Credentials invalid – stay on /login and surface the error
        self._login_error = "Invalid credentials"
        return None

    def logout(self) -> rx.EventSpec:
        """Clear the session and return to /login."""
        self._username = ""
        self._role = ""
        self._login_error = ""
        return rx.redirect("/login")

    # --- on_load guards ---

    def require_auth(self) -> rx.EventSpec | None:
        """Redirect to /login if not authenticated."""
        if not self.is_authenticated:
            return rx.redirect("/login")

    def require_admin(self) -> rx.EventSpec | None:
        """Redirect unauthenticated → /login, non-admin → /forbidden."""
        if not self.is_authenticated:
            return rx.redirect("/login")
        if not self.is_admin:
            return rx.redirect("/forbidden")


# ---------------------------------------------------------------------------
# Pages
# ---------------------------------------------------------------------------

def login_page() -> rx.Component:
    """Public login page at /login."""
    return rx.center(
        rx.card(
            rx.vstack(
                rx.heading("Sign In", size="6", margin_bottom="1em"),
                rx.form(
                    rx.vstack(
                        rx.input(
                            placeholder="Username",
                            name="username",
                            required=True,
                            width="100%",
                        ),
                        rx.input(
                            placeholder="Password",
                            name="password",
                            type="password",
                            required=True,
                            width="100%",
                        ),
                        rx.cond(
                            State.login_error != "",
                            rx.text(
                                State.login_error,
                                color="red",
                                id="login-error",
                            ),
                        ),
                        rx.button(
                            "Login",
                            type="submit",
                            width="100%",
                        ),
                        spacing="3",
                        width="100%",
                    ),
                    on_submit=State.login,
                    reset_on_submit=False,
                    width="100%",
                ),
                width="100%",
                spacing="4",
            ),
            width="360px",
            padding="2em",
        ),
        min_height="100vh",
    )


def dashboard_page() -> rx.Component:
    """Protected page at /dashboard – any authenticated user."""
    return rx.center(
        rx.vstack(
            rx.heading("Dashboard", size="8"),
            rx.text(
                "Logged in as: ",
                rx.text.span(State.current_username, font_weight="bold"),
            ),
            rx.text(
                "Role: ",
                rx.text.span(State.current_role, font_weight="bold"),
            ),
            rx.button("Logout", on_click=State.logout, color_scheme="red"),
            spacing="4",
            align="center",
        ),
        min_height="100vh",
    )


def admin_page() -> rx.Component:
    """Protected page at /admin – admin role only."""
    return rx.center(
        rx.vstack(
            rx.heading("Admin Panel", size="8"),
            rx.text("Welcome, administrator!"),
            rx.hstack(
                rx.link(rx.button("Dashboard"), href="/dashboard"),
                rx.button("Logout", on_click=State.logout, color_scheme="red"),
                spacing="3",
            ),
            spacing="4",
            align="center",
        ),
        min_height="100vh",
    )


def forbidden_page() -> rx.Component:
    """Public page at /forbidden."""
    return rx.center(
        rx.vstack(
            rx.heading("Access Denied", size="8", color="red"),
            rx.text("You do not have permission to view that page."),
            rx.link(rx.button("Go to Dashboard"), href="/dashboard"),
            spacing="4",
            align="center",
        ),
        min_height="100vh",
    )


# ---------------------------------------------------------------------------
# App assembly
# ---------------------------------------------------------------------------

app = rx.App()

app.add_page(login_page, route="/login")
app.add_page(
    dashboard_page,
    route="/dashboard",
    on_load=State.require_auth,
)
app.add_page(
    admin_page,
    route="/admin",
    on_load=State.require_admin,
)
app.add_page(forbidden_page, route="/forbidden")

# Redirect root to login
app.add_page(lambda: rx.redirect("/login"), route="/")

